"""
    get rid of possible spaces around farm location string
    """
def preprocess_location(location: Any) -> object {
    locations = location.split(',');
    res = "";
    for location in locations {
        res = res + location.strip() + ",";
    }
    res = res[:-1];
    return res;
}

